// Dev harness: extract the pure physics core + self-test from index.html and
// run them headless in node. No DOM. Usage: node test.mjs
import { readFileSync } from 'node:fs';
import { fileURLToPath } from 'node:url';
import { dirname, join } from 'node:path';

const here = dirname(fileURLToPath(import.meta.url));
const html = readFileSync(join(here, 'index.html'), 'utf8');

function block(id) {
  const start = html.indexOf(`<script id="${id}">`);
  const end = html.indexOf(`</script>`, start);
  if (start < 0 || end < 0) throw new Error('missing <script id="' + id + '">');
  return html.slice(start + `<script id="${id}">`.length, end);
}

// Evaluate both pure blocks in this global scope, in order.
const core = block('physics-core');
const selftest = block('selftest');
(0, eval)(core);
(0, eval)(selftest);

const r = globalThis.__d20SelfTest(50);
// compact machine summary
console.log('SUMMARY settled=' + r.settled + '/' + r.throws +
  ' within20=' + r.within20 + ' det=' + (r.detPass ? 'PASS' : 'FAIL') +
  ' distinct=' + r.distinct);

// throwFromFling headless checks (wrist fling -> single impulse)
const D = globalThis.D20;
const near = (a, b) => Math.abs(a - b) < 1e-9;
const vEq = (a, b, eps) => a[0]===b[0] && a[1]===b[1] && a[2]===b[2] ? true
  : Math.abs(a[0]-b[0])<eps && Math.abs(a[1]-b[1])<eps && Math.abs(a[2]-b[2])<eps;
let fail = false;

// (a) exact impulse math: fresh die at rest, J = m*v at grabPoint.
{
  const die = D.createD20();
  die.pos = [0.05, 0.10, 0.03]; die.vel = [0,0,0]; die.angVel = [0,0,0]; die.quat = [0,0,0,1];
  const grab = [0.06, 0.12, 0.04];
  const v = [2.0, 0.5, 1.5];            // |v| < 9, so not clamped
  const J = D.throwFromFling(die, grab, v);
  const m = die.geo.mass;
  // linear: vel = J/m = v exactly
  const linOK = vEq(die.vel, v, 0);
  // angular: angVel = invInertia * (r x J), r = grab - pos
  const r = [grab[0]-die.pos[0], grab[1]-die.pos[1], grab[2]-die.pos[2]];
  const cross = [r[1]*J[2]-r[2]*J[1], r[2]*J[0]-r[0]*J[2], r[0]*J[1]-r[1]*J[0]];
  const inv = die.geo.invInertia;
  const expAng = [
    inv[0][0]*cross[0]+inv[0][1]*cross[1]+inv[0][2]*cross[2],
    inv[1][0]*cross[0]+inv[1][1]*cross[1]+inv[1][2]*cross[2],
    inv[2][0]*cross[0]+inv[2][1]*cross[1]+inv[2][2]*cross[2]
  ];
  const angOK = vEq(die.angVel, expAng, 0);
  const jOK = vEq(J, [m*v[0], m*v[1], m*v[2]], 0);
  const okA = linOK && angOK && jOK;
  console.log('fling math: ' + (okA ? 'PASS' : 'FAIL') +
    ' (vel=' + die.vel + ' angVel=' + die.angVel + ')');
  okA || (console.error('  FAIL detail: linOK=' + linOK + ' angOK=' + angOK +
    ' jOK=' + jOK + ' expAng=' + expAng), fail = true);
}
// (b) speed clamp: a 12 m/s fling is clamped to 9 m/s.
{
  const die = D.createD20();
  die.vel = [0,0,0]; die.angVel = [0,0,0]; die.quat = [0,0,0,1];
  const grab = [die.pos[0]+0.02, die.pos[1]+0.02, die.pos[2]+0.02];
  const v = [12, 0, 0];
  const J = D.throwFromFling(die, grab, v);
  // J = m*9 in +x; linear speed |v| after = 9
  const speed = Math.sqrt(die.vel[0]**2 + die.vel[1]**2 + die.vel[2]**2);
  const okB = near(speed, 9) && near(J[0], die.geo.mass*9);
  console.log('fling clamp: ' + (okB ? 'PASS' : 'FAIL') +
    ' (speed=' + speed.toFixed(6) + ' J=' + J[0].toFixed(6) + ')');
  okB || (console.error('  FAIL detail: speed=' + speed + ' expected 9'), fail = true);
}
// (c) full wrist throw: seeded start, fling, advance to settle -> faceUp 1..20.
{
  const die = D.createD20();
  die.pos = [0.02, 0.12, -0.01]; die.vel = [0,0,0]; die.angVel = [0,0,0]; die.quat = [0,0,0,1];
  const grab = [0.03, 0.14, 0.01];
  const v = [2.5, -0.3, 1.8];
  D.throwFromFling(die, grab, v);
  D.advance(die, 25);
  const okC = die.settled && die.result >= 1 && die.result <= 20;
  console.log('fling settle: ' + (okC ? 'PASS' : 'FAIL') +
    ' (settled=' + die.settled + ' faceUp=' + die.result + ' t=' + die.t.toFixed(2) + ')');
  okC || (console.error('  FAIL detail: settled=' + die.settled + ' result=' + die.result), fail = true);
}

// hard assertions
let ok = !fail;
if (r.settled !== r.throws) { console.error('FAIL: not all settled'); ok = false; }
if (!r.detPass) { console.error('FAIL: determinism'); ok = false; }
if (r.distinct < 4) { console.error('FAIL: too little spread (' + r.distinct + ')'); ok = false; }
console.log(ok ? 'RESULT PASS' : 'RESULT FAIL');
process.exit(ok ? 0 : 1);
