    console.log('throws=' + nThrows + ' settled=' + settled + '/' + nThrows +
      ' within20s=' + within20 + ' over20s=' + over20);
    console.log('determinism=' + (detPass ? 'PASS' : 'FAIL') +
      ' (faces ' + a.result + ' == ' + b.result + ')');
    console.log('distinct faces=' + distinct + '  hist=' + histStr);
    console.log('samples=' + results.slice(0, 20).join(','));
    return { throws: nThrows, settled, within20, over20, detPass,
             detFaces: [a.result, b.result], distinct, hist, samples: results };
  }

